import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64
.visible .entry sigmoid_forward(
    .param .u64 in_ptr,
    .param .u64 out_ptr,
    .param .u32 numel
)
{
    .reg .pred %p<8>;
    .reg .b32 %r<32>;
    .reg .b64 %rd<24>;
    .reg .f32 %f<32>;
    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [out_ptr];
    ld.param.u32 %r5, [numel];
    mov.u32 %r1, %ctaid.x;
    mov.u32 %r2, %ntid.x;
    mov.u32 %r3, %tid.x;
    mad.lo.u32 %r4, %r1, %r2, %r3;      // first quad index
    mov.u32 %r8, %nctaid.x;
    mul.lo.u32 %r9, %r8, %r2;           // quad stride = gridDim.x * blockDim.x
    mul.lo.u32 %r6, %r4, 4;             // first base element index
    mul.lo.u32 %r10, %r9, 4;            // element-index stride per grid step
    add.u32 %r13, %r10, %r10;           // two-quad element stride
    mul.wide.u32 %rd9, %r9, 16;         // byte stride per grid step (4 floats per quad)
    add.s64 %rd11, %rd9, %rd9;          // two-quad byte stride
    mul.wide.u32 %rd3, %r6, 4;
    add.s64 %rd4, %rd1, %rd3;           // running input pointer
    add.s64 %rd5, %rd2, %rd3;           // running output pointer
QUAD_LOOP:
    setp.ge.u32 %p1, %r6, %r5;          // base >= numel?
    @%p1 bra DONE;                      // no more work for this thread
    sub.u32 %r14, %r5, %r6;             // remaining elements from first base
    setp.ge.u32 %p2, %r14, 4;           // first full quad in bounds?
    @!%p2 bra TAIL_LOOP;
    add.u32 %r11, %r6, %r10;            // second quad base, one grid step ahead
    setp.ge.u32 %p3, %r11, %r5;
    @%p3 bra SINGLE_QUAD;
    sub.u32 %r15, %r5, %r11;            // remaining elements from second base
    setp.ge.u32 %p4, %r15, 4;           // second full quad in bounds?
    @!%p4 bra SINGLE_QUAD;
    add.s64 %rd6, %rd4, %rd9;           // second input pointer
    add.s64 %rd7, %rd5, %rd9;           // second output pointer
    ld.global.v4.f32 {%f1, %f2, %f3, %f4}, [%rd4];
    ld.global.v4.f32 {%f9, %f10, %f11, %f12}, [%rd6];
    mul.f32 %f5, %f1, 0fBFB8AA3B;       // -x * log2(e)
    ex2.approx.f32 %f5, %f5;            // exp(-x)
    add.f32 %f5, %f5, 0f3F800000;       // 1 + exp(-x)
    rcp.approx.f32 %f1, %f5;            // 1 / (1 + exp(-x)) via fast reciprocal
    mul.f32 %f6, %f2, 0fBFB8AA3B;
    ex2.approx.f32 %f6, %f6;
    add.f32 %f6, %f6, 0f3F800000;
    rcp.approx.f32 %f2, %f6;
    mul.f32 %f7, %f3, 0fBFB8AA3B;
    ex2.approx.f32 %f7, %f7;
    add.f32 %f7, %f7, 0f3F800000;
    rcp.approx.f32 %f3, %f7;
    mul.f32 %f8, %f4, 0fBFB8AA3B;
    ex2.approx.f32 %f8, %f8;
    add.f32 %f8, %f8, 0f3F800000;
    rcp.approx.f32 %f4, %f8;
    st.global.v4.f32 [%rd5], {%f1, %f2, %f3, %f4};
    mul.f32 %f13, %f9, 0fBFB8AA3B;
    ex2.approx.f32 %f13, %f13;
    add.f32 %f13, %f13, 0f3F800000;
    rcp.approx.f32 %f9, %f13;
    mul.f32 %f14, %f10, 0fBFB8AA3B;
    ex2.approx.f32 %f14, %f14;
    add.f32 %f14, %f14, 0f3F800000;
    rcp.approx.f32 %f10, %f14;
    mul.f32 %f15, %f11, 0fBFB8AA3B;
    ex2.approx.f32 %f15, %f15;
    add.f32 %f15, %f15, 0f3F800000;
    rcp.approx.f32 %f11, %f15;
    mul.f32 %f16, %f12, 0fBFB8AA3B;
    ex2.approx.f32 %f16, %f16;
    add.f32 %f16, %f16, 0f3F800000;
    rcp.approx.f32 %f12, %f16;
    st.global.v4.f32 [%rd7], {%f9, %f10, %f11, %f12};
    add.s64 %rd4, %rd4, %rd11;          // advance running pointers by two grid steps
    add.s64 %rd5, %rd5, %rd11;
    add.u32 %r6, %r6, %r13;             // advance base element index by two quads strides
    bra QUAD_LOOP;
SINGLE_QUAD:
    ld.global.v4.f32 {%f1, %f2, %f3, %f4}, [%rd4];
    mul.f32 %f5, %f1, 0fBFB8AA3B;
    ex2.approx.f32 %f5, %f5;
    add.f32 %f5, %f5, 0f3F800000;
    rcp.approx.f32 %f1, %f5;
    mul.f32 %f6, %f2, 0fBFB8AA3B;
    ex2.approx.f32 %f6, %f6;
    add.f32 %f6, %f6, 0f3F800000;
    rcp.approx.f32 %f2, %f6;
    mul.f32 %f7, %f3, 0fBFB8AA3B;
    ex2.approx.f32 %f7, %f7;
    add.f32 %f7, %f7, 0f3F800000;
    rcp.approx.f32 %f3, %f7;
    mul.f32 %f8, %f4, 0fBFB8AA3B;
    ex2.approx.f32 %f8, %f8;
    add.f32 %f8, %f8, 0f3F800000;
    rcp.approx.f32 %f4, %f8;
    st.global.v4.f32 [%rd5], {%f1, %f2, %f3, %f4};
    add.s64 %rd4, %rd4, %rd9;           // advance running pointers by byte stride
    add.s64 %rd5, %rd5, %rd9;
    add.u32 %r6, %r6, %r10;             // advance base element index
    bra QUAD_LOOP;
TAIL_LOOP:
    setp.ge.u32 %p5, %r6, %r5;
    @%p5 bra DONE;
    ld.global.f32 %f1, [%rd4];
    mul.f32 %f2, %f1, 0fBFB8AA3B;
    ex2.approx.f32 %f2, %f2;
    add.f32 %f2, %f2, 0f3F800000;
    rcp.approx.f32 %f2, %f2;
    st.global.f32 [%rd5], %f2;
    add.s64 %rd4, %rd4, 4;
    add.s64 %rd5, %rd5, 4;
    add.u32 %r6, %r6, 1;
    bra TAIL_LOOP;
DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("sigmoid_forward")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        module = _get_ptx_module()
        out = torch.empty_like(x)
        n = x.numel()
        quads = (n + 3) // 4
        block_x = 512
        blocks_needed = (quads + block_x - 1) // block_x
        grid_x = max(1, min(blocks_needed, 4096))  # capped grid; kernel grid-stride loop covers the rest
        module.launch(
            "sigmoid_forward",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[u64(x.data_ptr()), u64(out.data_ptr()), u32(n)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
